(function () {
    "use strict";
    const params = new URLSearchParams(location.search);
    const requested = Number(params.get("chapter"));
    const chapter = Number.isInteger(requested) && requested >= 1 && requested <= 18 ? requested : 1;
    const root = document.getElementById("impress");
    const status = document.getElementById("chapter-status");
    const previous = document.getElementById("previous-verse");
    const next = document.getElementById("next-verse");
    let presentation;
    let steps = [];

    document.title = chapter + " — श्रीमद्भगवद्गीता";
    document.getElementById("chapter-label").textContent = "अध्यायः " +
        String(chapter).replace(/\d/g, digit => "०१२३४५६७८९"[digit]);

    function navigate(direction) {
        if (!presentation) return;
        const active = steps.findIndex(step => step.classList.contains("active"));
        presentation.goto((Math.max(0, active) + direction + steps.length) % steps.length);
    }

    previous.addEventListener("click", () => navigate(-1));
    next.addEventListener("click", () => navigate(1));

    async function loadChapter() {
        try {
            const response = await fetch("./verse.json");
            if (!response.ok) throw new Error("Verse request failed: " + response.status);
            const data = await response.json();
            const verses = data.filter(verse => Number(verse.chapter_number) === chapter);
            if (!verses.length) throw new Error("No verses for chapter " + chapter);

            const fragment = document.createDocumentFragment();
            chapterLayouts[chapter].forEach((layout, index) => {
                const slide = document.createElement("div");
                slide.id = "step-" + (index + 1);
                Object.entries(layout).forEach(([name, value]) => {
                    if (name === "html") slide.innerHTML = value;
                    else slide.setAttribute(name, value);
                });
                fragment.append(slide);
            });
            root.replaceChildren(fragment);
            steps = Array.from(root.querySelectorAll(".step"));

            verses.forEach((verse, index) => {
                const slide = steps[index];
                const text = document.createElement("span");
                text.className = "verse-text";
                text.textContent = Sanscript.t(verse.text, "iast", "devanagari");
                const reference = document.createElement("a");
                const url = new URL("https://www.gitasupersite.iitk.ac.in/srimad");
                url.searchParams.set("language", "dv");
                url.searchParams.set("field_chapter_value", verse.chapter_number);
                url.searchParams.set("field_nsutra_value", verse.verse_number);
                reference.href = url.href;
                reference.target = "gss";
                reference.rel = "noopener";
                reference.textContent = "॥ " + verse.chapter_number + "." + verse.verse_number + " ॥";
                slide.append(text, document.createTextNode(" "), reference, document.createElement("br"));
            });

            presentation = impress();
            presentation.init();
            previous.disabled = false;
            next.disabled = false;
            status.hidden = true;
        } catch (error) {
            status.textContent = "The verses could not be loaded. Please refresh to try again.";
            console.error("Could not load chapter:", error);
        }
    }

    loadChapter();
}());
